package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

import org.junit.jupiter.api.Test;

/**
 * Pins the hedge evidence rules: a winning backup earns safety credit while probes never do, contended completions
 * record at a reduced weight through the ordinary recording path, severe censors (only) accumulate in the drift
 * detector until systemic mispricing bumps the regime epoch, a quarantined incumbent yields to a measured rival on the
 * very next dispatch (anti-ping-pong), and a probe that blows far past its deadline is quarantined outright as
 * not-cooperatively-cancellable.
 */
class LmdbNativeHedgeEvidenceTest {

	@Test
	void hedgeBackupsEarnSafetyCreditAndProbesNeverDo() {
		for (LmdbNativeCostObservation.Role role : LmdbNativeCostObservation.Role.values()) {
			LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
			LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(),
					store, new LmdbNativeAdaptiveCostModel.Configuration(true, true));
			FakeClock clock = new FakeClock();
			LmdbNativeCostObservation observation = new LmdbNativeCostObservation(estimate("arm"), model, clock,
					role);
			clock.advance(1_000_000L);
			observation.exhausted();
			long credit = store.safetyLedger().availableNanos();
			if (role == LmdbNativeCostObservation.Role.PROBE) {
				assertEquals(0L, credit, "a probe never earns");
			} else {
				assertTrue(credit > 0L, role + " must earn safety credit for useful work");
			}
		}
	}

	@Test
	void contendedCompletionsRecordAtReducedWeight() {
		double cleanNEff = nEffAfterTwoCompletions(false);
		double contendedNEff = nEffAfterTwoCompletions(true);
		assertTrue(contendedNEff < cleanNEff,
				"a completion that overlapped a live sibling must carry less effective evidence: clean=" + cleanNEff
						+ " contended=" + contendedNEff);
	}

	private static double nEffAfterTwoCompletions(boolean secondContended) {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		LmdbNativeCostEstimate estimate = estimate("arm");
		for (int i = 0; i < 2; i++) {
			FakeClock clock = new FakeClock();
			LmdbNativeCostObservation observation = new LmdbNativeCostObservation(estimate, model, clock,
					LmdbNativeCostObservation.Role.NORMAL);
			if (i == 1 && secondContended) {
				observation.markContended(LmdbNativeHedgeConfig.defaults().evidenceWeight());
			}
			clock.advance(1_000_000L);
			observation.exhausted();
		}
		return model.predict(estimate).nEff();
	}

	@Test
	void severeCensorsAccumulateInTheDriftDetectorUntilTheEpochBumps() {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		LmdbNativeCostEstimate estimate = estimate("arm");
		LmdbNativeRegimeKey regime = model.currentRegime();
		for (int i = 0; i < 8; i++) {
			model.recordCompleted(estimate, estimate.total(), 1_000_000.0, 1.0, regime);
		}
		long epochBefore = store.regimeTracker().epoch();
		long deadline = 100_000_000L;
		boolean sawSevere = false;
		for (int i = 0; i < 20 && store.regimeTracker().epoch() == epochBefore; i++) {
			LmdbNativeAdaptiveCostModel.CensorResult censor = model.recordCensored(estimate, deadline, null, regime);
			sawSevere |= censor.severeMiss();
			deadline *= 2; // the Mills-ratio ratchet raises the posterior; keep the bound above high99
		}
		assertTrue(sawSevere, "the escalating deadlines must register as severe misses");
		assertNotEquals(epochBefore, store.regimeTracker().epoch(),
				"accumulated severe censors must trip Page-Hinkley and bump the epoch");
	}

	@Test
	void aQuarantinedIncumbentYieldsToTheMeasuredRunnerUp() {
		LmdbNativeAdaptiveArbitration.Priced<String> quarantined = pricedArm("incumbent", 0, 1_000_000.0, true);
		LmdbNativeAdaptiveArbitration.Priced<String> rival = pricedArm("rival", 1, 5_000_000.0, false);
		LmdbNativeAdaptiveArbitration.Priced<String> rescued = LmdbNativeAdaptiveArbitration
				.coldStartRescue(List.of(quarantined, rival));
		assertSame(rival, rescued, "the dispatch after a guard loss must pick the runner-up outright");

		LmdbNativeAdaptiveArbitration.Priced<String> healthy = pricedArm("incumbent", 0, 1_000_000.0, false);
		assertNull(LmdbNativeAdaptiveArbitration.coldStartRescue(List.of(healthy, rival)),
				"a healthy measured incumbent is never rescued away");
	}

	@Test
	void aProbeBlowingFarPastItsDeadlineIsQuarantinedOutright() throws IOException {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		LmdbNativeStrategyProposal<String> template = proposal("incumbent", LmdbNativeWork.exact(1_000D), () -> {
			return "incumbent";
		});
		LmdbNativeCostEstimate incumbentEstimate = template.adaptiveEstimate(-1D);
		for (int i = 0; i < 30; i++) {
			model.recordCompleted(incumbentEstimate, incumbentEstimate.total(), 5_000_000.0, 1.0,
					model.currentRegime());
		}
		store.safetyLedger().earn(1_000_000_000_000L);

		// the rival ignores every poll until it has slept far past the 4 ms deadline: cancellation lag, not slowness
		AtomicInteger rivalOpens = new AtomicInteger();
		LmdbNativeStrategyProposal<String> rival = proposal("rival", LmdbNativeWork.UNKNOWN, () -> {
			rivalOpens.incrementAndGet();
			try {
				Thread.sleep(80L); // >= 4x the 4 ms deadline
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			}
			int tick = 0;
			while (true) {
				LmdbNativeProbeDeadline.poll(++tick);
			}
		});
		LmdbNativeCostEstimate rivalEstimate = rival.directTimingEstimate();

		String result;
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter
				.<String>forModel(null, -1D, model)
				.probeHarness(LmdbNativeProbeHarness.blocking())) {
			arbiter.offer(() -> proposal("incumbent", LmdbNativeWork.exact(1_000D), () -> "incumbent"));
			arbiter.offer(() -> rival);
			result = arbiter.select();
		}

		assertEquals("incumbent", result);
		assertEquals(1, rivalOpens.get());
		assertEquals(LmdbNativeProbeScheduler.State.QUARANTINED,
				store.probeScheduler()
						.state(rivalEstimate.variantKey(), model.currentRegime(), 0L),
				"an arm that proved not-cooperatively-cancellable is quarantined, not merely cooled down");
	}

	// ---------------------------------------------------------------------------------------------------------

	private static LmdbNativeStrategyProposal<String> proposal(String value, LmdbNativeWork work,
			LmdbNativeStrategyProposal.Opener<String> opener) {
		return new LmdbNativeStrategyProposal<>(opener, work,
				value.equals("incumbent") ? LmdbNativeAttemptMetrics.PATH_BATCH
						: LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES,
				() -> {
				});
	}

	private static LmdbNativeCostEstimate estimate(String family) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, 100);
		return new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector, 100, 0.1);
	}

	private static LmdbNativeAdaptiveArbitration.Priced<String> pricedArm(String family, int preference,
			double expected, boolean quarantined) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, expected);
		LmdbNativeCostEstimate estimate = new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector,
				expected, 0.1);
		LmdbNativeCostPrediction.Components components = new LmdbNativeCostPrediction.Components(
				LmdbNativeRegimeKey.STEADY, LmdbNativeCostPosteriorStore.Lane.DIRECT,
				LmdbNativeFamilyShapeKey.of(key), 0.0, Math.log(expected), 0.0, 0.0, 0.01, 0.0);
		LmdbNativeCostPrediction prediction = new LmdbNativeCostPrediction(expected * 0.8, expected, expected * 1.2,
				expected * 0.7, expected * 1.4, expected * 0.7, expected * 1.4,
				LmdbNativeCostPrediction.PriceBasis.DIRECT_POSTERIOR, true, quarantined, 64.0, 64L,
				LmdbNativeCostPrediction.EvidenceSource.EXACT_VARIANT, components, "test");
		return new LmdbNativeAdaptiveArbitration.Priced<>(
				new LmdbNativeAdaptiveArbitration.Candidate<>(estimate, preference, observation -> family),
				prediction);
	}

	private static final class FakeClock implements LmdbNativeCostObservation.NanoClock {
		private final AtomicLong now = new AtomicLong();

		@Override
		public long nanoTime() {
			return now.get();
		}

		void advance(long nanos) {
			now.addAndGet(nanos);
		}
	}
}
